                objs.append((r+1,c+1,color))
    for r,c,col in objs:
        for x in range(w):
            if g[r][x]==0: g[r][x]=col
        for y in range(h):
            if g[y][c]==0: g[y][c]=col
        # Fill the entire object row/column as the ray runs through the 3x3.
        for x in range(w):
            if x not in range(c-1,c+2) and g[r][x]==0: g[r][x]=col
        for y in range(h):
            if y not in range(r-1,r+2) and g[y][c]==0: g[y][c]=col
    # Crossings between rays of different colors are left blank.
    for r,c,col in objs:
        for rr,cc,other in objs:
            if col!=other:
                g[r][cc]=0
                g[rr][c]=0
    return g

